using Aspire.Hosting.Testing;
using Microsoft.Extensions.AI;
using Microsoft.Extensions.AI.Evaluation;
using Microsoft.Extensions.AI.Evaluation.Quality;
using Microsoft.Extensions.AI.Evaluation.Reporting;
using Microsoft.Extensions.DependencyInjection;

namespace MyApp.Evaluation;

[TestClass]
public sealed class EvaluationTests
{
    private static DistributedApplicationTestingBuilder _appHost = null!;
    private static DistributedApplication _app = null!;
    private static IChatClient _chatClient = null!;
    private static ReportingConfiguration _reportingConfig = null!;

    [ClassInitialize]
    public static async Task ClassInit(TestContext context)
    {
        _appHost = await DistributedApplicationTestingBuilder.CreateAsync<Projects.MyApp_AppHost>();
        _appHost.Services.ConfigureHttpClientDefaults(b => b.AddStandardResilienceHandler());
        _app = await _appHost.BuildAsync();
        await _app.StartAsync();

        _chatClient = _app.Services.GetRequiredService<IChatClient>();

        var evaluators = new IEvaluator[]
        {
            new CoherenceEvaluator(),
            new RelevanceEvaluator(),
            new GroundednessEvaluator(),
            new FluencyEvaluator(),
        };

        _reportingConfig = new ReportingConfiguration(
            evaluators,
            reportStorageRootPath: Path.Combine(
                context.TestRunResultsDirectory ?? ".",
                "EvaluationReports"));
    }

    [ClassCleanup]
    public static async Task ClassCleanup()
    {
        await _app.DisposeAsync();
        await _appHost.DisposeAsync();
    }

    [TestMethod]
    [DynamicData(nameof(GetScenarios), DynamicDataSourceType.Method)]
    public async Task EvaluateScenario(string scenarioName, string userPrompt, string? context)
    {
        await using var scenario = await _reportingConfig.CreateScenarioRunAsync(scenarioName);

        var messages = new List<ChatMessage> { new(ChatRole.User, userPrompt) };
        var response = await _chatClient.GetResponseAsync(messages);
        var modelResponse = response.Text ?? string.Empty;

        await scenario.EvaluateAsync(
            messages,
            new ChatMessage(ChatRole.Assistant, modelResponse),
            additionalContext:
                context is not null
                    ? [new EvaluationContext("grounding", context)]
                    : []);
    }

    private static IEnumerable<object?[]> GetScenarios()
    {
        var scenariosDir = Path.Combine(AppContext.BaseDirectory, "Scenarios");
        if (!Directory.Exists(scenariosDir))
            yield break;

        foreach (var file in Directory.GetFiles(scenariosDir, "*.json"))
        {
            var scenarios = System.Text.Json.JsonSerializer.Deserialize<EvaluationScenario[]>(
                File.ReadAllText(file));

            if (scenarios is null) continue;

            foreach (var s in scenarios)
            {
                yield return [s.Name, s.Prompt, s.Context];
            }
        }
    }
}

public sealed record EvaluationScenario(string Name, string Prompt, string? Context);

